from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    if not elf.has_dwarf_info():
        print('No DWARF info')
        exit()
    dwarf = elf.get_dwarf_info()

    addrs = [0x2f4b20, 0x2f4c84, 0x2c1a40]
    for addr in addrs:
        for CU in dwarf.iter_CUs():
            lineprog = dwarf.line_program_for_CU(CU)
            if lineprog is None:
                continue
            prev_state = None
            for entry in lineprog.get_entries():
                if entry.state is None:
                    continue
                if prev_state and prev_state.address <= addr < entry.state.address:
                    filename = lineprog['file_entry'][prev_state.file - 1].name.decode() if prev_state.file > 0 else '?'
                    print(f'0x{addr:x} -> {filename}:{prev_state.line}')
                    break
                if entry.state.end_sequence:
                    prev_state = None
                else:
                    prev_state = entry.state
            else:
                continue
            break
        else:
            print(f'0x{addr:x} -> not found in DWARF')
" 2>&1

